package postman

import (
	"bytes"
	"encoding/json"
	"strings"
)

// mergeRequest combines a request regenerated from the spec (new) with the
// existing request (old), keeping data the user edited in Postman. base is the
// request generated by the previous sync, or nil when unknown.
//
// With a baseline (three-way merge), each user-editable field (value, enabled
// state) follows the spec when old still equals base and is kept otherwise.
// Entries only in old are kept when they are not in base (added by hand) and
// dropped when they are (removed from the spec); entries in base and new but
// not in old were deleted by hand and stay deleted.
//
// Without a baseline (two-way merge), matched entries keep their old value and
// enabled state, and an old-only entry is considered hand-added when it has no
// description (Postman's importer always copies the spec description).
//
// Descriptions, method, URL structure and everything else come from new.
func mergeRequest(old, base, new *Request) *Request {
	if old == nil || new == nil {
		return new
	}
	var baseHeaders []Header
	var baseURL *URL
	var baseBody *Body
	if base != nil {
		baseHeaders, baseURL, baseBody = base.Header, base.URL, base.Body
	}
	out := *new
	out.Header = mergeByKey(old.Header, baseHeaders, base != nil, new.Header, headerMerge)
	out.URL = mergeURL(old.URL, baseURL, new.URL)
	out.Body = mergeBody(old.Body, baseBody, new.Body)
	return &out
}

func mergeURL(old, base, new *URL) *URL {
	if old == nil || new == nil {
		return new
	}
	var baseQuery []URLParam
	var baseVars []Variable
	if base != nil {
		baseQuery, baseVars = base.Query, base.Variable
	}
	out := *new
	out.Query = mergeByKey(old.Query, baseQuery, base != nil, new.Query, urlParamMerge)
	out.Variable = mergeByKey(old.Variable, baseVars, base != nil, new.Variable, pathVariableMerge)
	return &out
}

func mergeBody(old, base, new *Body) *Body {
	if old == nil || new == nil || old.Mode != new.Mode {
		return new
	}
	if base != nil && base.Mode != old.Mode {
		base = nil // the baseline describes a different body; it tells us nothing
	}

	out := *new
	out.Disabled = keep(old.Disabled, new.Disabled, base != nil && old.Disabled == base.Disabled)
	switch new.Mode {
	case "raw":
		var baseRaw *string
		if base != nil {
			baseRaw = &base.Raw
		}
		out.Raw = mergeRawBody(old.Raw, baseRaw, new.Raw)
	case "formdata":
		var baseForm []FormParam
		if base != nil {
			baseForm = base.FormData
		}
		out.FormData = mergeByKey(old.FormData, baseForm, base != nil, new.FormData, formParamMerge)
	case "urlencoded":
		var baseForm []FormParam
		if base != nil {
			baseForm = base.URLEncoded
		}
		out.URLEncoded = mergeByKey(old.URLEncoded, baseForm, base != nil, new.URLEncoded, formParamMerge)
	default:
		// graphql, file, ...: no structure to reconcile.
		if base != nil && sameJSON(old, base) {
			return new
		}
		return old
	}
	return &out
}

// keep returns new when the user left the field untouched since the baseline
// and old otherwise.
func keep[V any](old, new V, untouched bool) V {
	if untouched {
		return new
	}
	return old
}

func sameJSON(a, b any) bool {
	ja, errA := json.Marshal(a)
	jb, errB := json.Marshal(b)
	return errA == nil && errB == nil && bytes.Equal(ja, jb)
}

// keyedMerge describes how to merge a list of key/value entries.
type keyedMerge[T any] struct {
	// key identifies an entry; entries with the same key are merged.
	key func(T) string
	// carry returns the spec entry (new) with the user-owned fields of old,
	// except those the user left untouched since base (nil when unknown).
	carry func(old T, base *T, new T) T
	// specOwned entries strictly follow the spec's set of keys (path variables
	// must match the URL path): nothing is kept as hand-added or hand-deleted.
	specOwned bool
	// generatedBySpec reports whether an entry came from the spec; used to
	// detect hand-added entries when there is no baseline.
	generatedBySpec func(T) bool
}

// mergeByKey returns the entries of new, in spec order, merged with the old
// entry of the same key, followed by the hand-added old entries. hasBase
// reports whether base is known (an empty base is still a valid baseline).
func mergeByKey[T any](old, base []T, hasBase bool, new []T, m keyedMerge[T]) []T {
	if len(old) == 0 && !hasBase {
		return new
	}
	oldByKey := indexByKey(old, m.key)
	baseByKey := indexByKey(base, m.key)

	out := make([]T, 0, len(new))
	seen := make(map[string]bool, len(new))
	for _, n := range new {
		k := m.key(n)
		if seen[k] {
			out = append(out, n)
			continue
		}
		seen[k] = true

		o, inOld := oldByKey[k]
		b, inBase := baseByKey[k]
		switch {
		case inOld && inBase && hasBase:
			out = append(out, m.carry(o, &b, n))
		case inOld:
			out = append(out, m.carry(o, nil, n))
		case inBase && hasBase && !m.specOwned:
			// Generated last time but no longer in Postman: deleted by hand.
		default:
			out = append(out, n)
		}
	}

	if m.specOwned {
		return out
	}
	for _, o := range old {
		k := m.key(o)
		if seen[k] {
			continue
		}
		seen[k] = true
		_, inBase := baseByKey[k]
		handAdded := !inBase
		if !hasBase {
			handAdded = !m.generatedBySpec(o)
		}
		if handAdded {
			out = append(out, o)
		}
	}
	return out
}

// indexByKey indexes entries by key; the first entry wins on duplicates.
func indexByKey[T any](entries []T, key func(T) string) map[string]T {
	m := make(map[string]T, len(entries))
	for _, e := range entries {
		k := key(e)
		if _, dup := m[k]; !dup {
			m[k] = e
		}
	}
	return m
}

// hasDescription reports whether an entry carries a description, which
// Postman's OpenAPI importer always copies from the spec.
func hasDescription(e Extra) bool {
	_, ok := e["description"]
	return ok
}

func derefString(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

var headerMerge = keyedMerge[Header]{
	key: func(h Header) string { return strings.ToLower(h.Key) },
	carry: func(old Header, base *Header, new Header) Header {
		new.Value = keep(old.Value, new.Value, base != nil && old.Value == base.Value)
		new.Disabled = keep(old.Disabled, new.Disabled, base != nil && old.Disabled == base.Disabled)
		return new
	},
	generatedBySpec: func(h Header) bool { return hasDescription(h.Extra) },
}

var urlParamMerge = keyedMerge[URLParam]{
	key: func(p URLParam) string { return derefString(p.Key) },
	carry: func(old URLParam, base *URLParam, new URLParam) URLParam {
		new.Value = keep(old.Value, new.Value, base != nil && derefString(old.Value) == derefString(base.Value))
		new.Disabled = keep(old.Disabled, new.Disabled, base != nil && old.Disabled == base.Disabled)
		return new
	},
	generatedBySpec: func(p URLParam) bool { return hasDescription(p.Extra) },
}

var pathVariableMerge = keyedMerge[Variable]{
	key: func(v Variable) string { return v.Key },
	carry: func(old Variable, base *Variable, new Variable) Variable {
		new.Value = keep(old.Value, new.Value, base != nil && old.Value == base.Value)
		return new
	},
	specOwned: true,
}

// formUserFields are the form field properties owned by the user; they live
// in Extra because Postman may send them as null or as arrays.
var formUserFields = []string{"value", "src"}

var formParamMerge = keyedMerge[FormParam]{
	key: func(p FormParam) string { return p.Key },
	carry: func(old FormParam, base *FormParam, new FormParam) FormParam {
		if old.Type != new.Type {
			return new // text ↔ file: the old value no longer applies
		}
		extra := make(Extra, len(new.Extra)+len(formUserFields))
		for k, v := range new.Extra {
			extra[k] = v
		}
		for _, k := range formUserFields {
			ov, inOld := old.Extra[k]
			untouched := base != nil && bytes.Equal(ov, base.Extra[k])
			if inOld && !untouched {
				extra[k] = ov
			}
		}
		new.Extra = extra
		new.Disabled = keep(old.Disabled, new.Disabled, base != nil && old.Disabled == base.Disabled)
		return new
	},
	generatedBySpec: func(p FormParam) bool { return hasDescription(p.Extra) },
}
